<script setup lang="ts">
import{onMounted,ref}from"vue";import{ProviderService,type ProviderConfiguration,type ProviderHealth}from"../../../../frontend/src/services/provider-service";
const service=new ProviderService({requestId:crypto.randomUUID(),traceId:crypto.randomUUID(),identityId:"local-user",identityKind:"user",tenantId:"local-default"});const items=ref<ProviderConfiguration[]>([]);const health=ref<Record<string,ProviderHealth>>({});const error=ref("");const form=ref({provider_id:"",display_name:"",kind:"model",endpoint:"https://",secret_reference:"vault://",capabilities:"chat",timeout_seconds:60});
async function load(){items.value=(await service.list()).items}async function add(){try{await service.register({...form.value,capabilities:form.value.capabilities.split(",").map(x=>x.trim()).filter(Boolean)});await load()}catch(e){error.value=e instanceof Error?e.message:"操作失败"}}async function test(id:string){try{health.value[id]=await service.test(id)}catch(e){error.value=e instanceof Error?e.message:"操作失败"}}onMounted(load);
</script>
<template><section class="providers"><strong>真实能力提供方</strong><div><input v-model="form.provider_id" placeholder="提供方 ID"><input v-model="form.display_name" placeholder="名称"><select v-model="form.kind"><option v-for="k in ['model','text','image','video','audio']" :key="k">{{k}}</option></select><input v-model="form.endpoint" placeholder="HTTPS Endpoint"><input v-model="form.secret_reference" placeholder="vault://密钥引用"><input v-model="form.capabilities" placeholder="能力，逗号分隔"><button @click="add">注册</button></div><p v-for="item in items" :key="item.provider_id">{{item.display_name}} · {{item.kind}} · {{health[item.provider_id]?.status||'unknown'}} <button @click="test(item.provider_id)">测试连接</button></p><p v-if="error">{{error}}</p></section></template>
<style scoped>.providers{padding:10px;background:#171a21;color:#eef1f7}.providers div{display:flex;gap:6px;flex-wrap:wrap}.providers input,.providers select,.providers button{padding:5px;background:#0f1116;color:inherit;border:1px solid #39404d}</style>
